  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Menyapa Orang Myanmar dengan Benar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Myanmar adalah tetangga ASEAN dengan budaya yang kaya, dan semakin banyak orang Indonesia yang berkunjung, berbisnis, atau berteman dengan orang Myanmar. Namun bahasa Myanmar (bahasa Burma) terdengar asing: tulisannya bulat-bulat seperti lingkaran, dan nadanya menentukan arti kata. Salah nada bisa mengubah makna sepenuhnya. Artikel ini membekalimu sapaan dasar yang aman dipakai sejak hari pertama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Bahasa Burma dan Sistem Nadanya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Myanmar adalah bahasa tonal dengan empat nada: nada datar-tinggi, nada rendah, nada berderit (creaky), dan nada berhenti. Kata yang sama dengan nada berbeda bisa berarti hal yang sama sekali lain. Kabar baiknya: untuk sapaan sehari-hari, kamu cukup menghafal pola nada tiap frasa seperti menghafal lagu pendek — tidak perlu teori linguistik yang rumit.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Aplikasi kamus Myanmar-Indonesia atau Myanmar-Inggris$txt$, $txt$Video penutur asli (YouTube) untuk meniru nada$txt$, $txt$Buku catatan kecil untuk menulis frasa dan artinya$txt$, $txt$Waktu 15 menit sehari selama dua minggu$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah: Kuasai Sapaan Dasar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Hafalkan "Mingalaba" (dibaca min-ga-la-ba): sapaan universal yang berarti halo sekaligus selamat, dipakai pagi sampai malam.$txt$, $txt$Pelajari kata ganti: "kyundaw" untuk saya (laki-laki) atau "kyunma" untuk saya (perempuan); "khinbya" untuk kamu secara sopan.$txt$, $txt$Hafalkan "kyeizu tin ba de" yang berarti terima kasih — frasa paling berguna kedua setelah sapaan.$txt$, $txt$Latih angka 1 sampai 5: tit (1), hnit (2), thone (3), lei (4), nga (5) untuk tawar-menawar dan menyebut jumlah.$txt$, $txt$Tirukan nada dari video penutur asli: dengarkan satu frasa, jeda video, ucapkan keras-keras, ulangi 10 kali.$txt$, $txt$Latih perkenalan pendek: "Kyundaw na-me ... ba" (nama saya ...) lalu "twe-ya-da wun-tha ba-de" (senang bertemu denganmu).$txt$, $txt$Coba dialog mini: A: "Mingalaba! Ne kaun la?" (Halo! Apa kabar?) — B: "Mingalaba! Kaun ba de." (Halo! Kabar baik.)$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kesalahan paling umum adalah mengucapkan semua kata dengan nada datar seperti bahasa Indonesia — akibatnya penutur asli sulit memahami atau menangkap arti yang berbeda. Jangan juga memakai sapaan akrab ke orang yang lebih tua; gunakan bentuk sopan. Terakhir, jangan menghafal tulisan latinnya saja tanpa mendengar audionya, karena ejaan latin bahasa Myanmar tidak konsisten antar sumber.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Kamu berhasil jika bisa menyapa "Mingalaba" dengan nada yang terdengar alami, memperkenalkan nama, mengucapkan terima kasih, dan menghitung 1–5 tanpa melihat catatan. Langkah berikutnya: pelajari frasa pasar ("be lau le?" = berapa harganya?) dan arah ("behma ...?" = di mana ...?).$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bahu Kaku Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bahu terasa kaku saat bangun tidur, sulit mengangkat tangan untuk mengambil barang di rak tinggi, atau nyeri saat memutar bahu — keluhan ini umum dialami pekerja kantoran, pengemudi, dan siapa pun yang lama duduk atau mengangkat beban. Kabar baiknya, sebagian besar bahu kaku ringan bisa membaik dengan peregangan rutin yang aman dilakukan di rumah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab Umum Bahu Kaku$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahu kaku biasanya disebabkan otot dan jaringan di sekitar sendi bahu yang tegang: postur membungkuk terlalu lama, tidur dengan posisi menekan satu bahu, gerakan berulang seperti mengangkat barang, atau kurang pemanasan sebelum olahraga. Pada kasus yang lebih serius, bisa berkaitan dengan peradangan sendi atau saraf terjepit — inilah mengapa penting mengenali tanda bahayanya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan Sebelum Peregangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Pastikan area sekitar lapang dan tidak licin$txt$, $txt$Kenakan pakaian longgar yang tidak membatasi gerak bahu$txt$, $txt$Lakukan pemanasan ringan 2 menit: jalan di tempat atau putar lengan perlahan$txt$, $txt$Siapkan handuk kecil sebagai alat bantu peregangan$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Peregangan Aman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Putaran bahu: angkat kedua bahu ke telinga, putar ke belakang 10 kali, lalu ke depan 10 kali dengan gerakan perlahan.$txt$, $txt$Peregangan silang: rentangkan lengan kanan lurus ke depan dada, tahan siku dengan tangan kiri selama 20 detik, ganti sisi.$txt$, $txt$Peregangan handuk: pegang handuk di belakang punggung dengan satu tangan di atas dan satu di bawah, tarik perlahan bergantian 5 kali tiap sisi.$txt$, $txt$Angkat dinding: hadapkan jari ke dinding, "merangkaklah" ke atas setinggi yang nyaman, tahan 10 detik, turunkan perlahan.$txt$, $txt$Bukakan dada: kaitkan kedua tangan di belakang punggung, luruskan siku, angkat perlahan sambil membuka dada, tahan 15 detik.$txt$, $txt$Lakukan rangkaian ini 1–2 kali sehari; setiap gerakan harus terasa meregang, bukan nyeri tajam.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Hal yang Perlu Diperhatikan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Berhenti segera jika muncul nyeri tajam, kesemutan, atau mati rasa$txt$, $txt$Jangan memaksa rentang gerak melebihi batas nyaman$txt$, $txt$Hindari gerakan menyentak atau memantul saat meregang$txt$, $txt$Jangan memijat area yang bengkak atau memar dengan keras$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Segera konsultasikan ke dokter jika bahu kaku disertai nyeri hebat setelah cedera atau jatuh, lengan terasa lemah atau mati rasa, bahu berubah bentuk, demam, atau kekakuan tidak membaik setelah dua minggu peregangan rutin. Tanda-tanda ini bisa menunjukkan masalah sendi, tendon, atau saraf yang butuh penanganan profesional. Catatan: artikel ini berisi informasi umum dan bukan pengganti nasihat medis; jika ragu dengan kondisimu, konsultasikan ke dokter atau fisioterapis sebelum melanjutkan program peregangan mandiri.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Teluk?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Teluk adalah bagian laut yang menjorok ke daratan, dikelilingi daratan di tiga sisinya dan terbuka ke samudra di satu sisi. Teluk terbentuk lewat berbagai proses: pergerakan lempeng tektonik, erosi glasial, hingga naik-turunnya permukaan laut selama ribuan tahun. Karena perairannya relatif terlindung dari ombak samudra lepas, teluk sejak zaman kuno menjadi lokasi ideal untuk pelabuhan dan permukiman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Teluk Benggala: yang Terbesar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Teluk Benggala di Samudra Hindia adalah teluk terbesar di dunia dengan luas sekitar 2,6 juta kilometer persegi — hampir satu setengah kali luas Indonesia bagian barat. Teluk ini berbatasan dengan India, Bangladesh, Myanmar, Sri Lanka, dan Thailand. Sungai-sungai besar seperti Gangga dan Brahmaputra bermuara di sini, membawa sedimen yang menyuburkan perairan dan menjadikannya salah satu daerah penangkapan ikan terpenting di Asia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Teluk Meksiko: Raksasa Atlantik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Teluk Meksiko memiliki luas sekitar 1,5 juta kilometer persegi, dikelilingi Amerika Serikat, Meksiko, dan Kuba. Teluk ini terkenal sebagai sumber minyak dan gas bumi lepas pantai, jalur pelayaran tersibuk, serta titik awal Arus Teluk (Gulf Stream) yang membawa air hangat ke Eropa Barat dan memengaruhi iklim di sana. Badai Atlantik yang kuat pun sering lahir di perairan hangat ini.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Teluk Hudson: Warisan Zaman Es$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Teluk Hudson di Kanada adalah teluk pedalaman raksasa dengan luas sekitar 1,2 juta kilometer persegi. Teluk ini terbentuk dari cekungan yang dikeruk gletser zaman es. Uniknya, daratan di sekitarnya masih "memantul" naik beberapa milimeter per tahun karena beban es yang dulu menekannya kini hilang — fenomena yang disebut rebound isostatik. Di musim dingin, teluk ini membeku dan menjadi habitat beruang kutub.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Peran Ekonomi dan Ancaman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Teluk-teluk besar menopang ekonomi miliaran manusia: pelabuhan dagang, ladang minyak dan gas lepas pantai, perikanan, dan pariwisata pesisir. Teluk Benggala misalnya menjadi jalur perdagangan vital bagi Bangladesh dan India timur, sementara Teluk Meksiko memasok sebagian besar hasil laut Amerika Serikat. Namun teluk-teluk ini menghadapi ancaman serupa: polusi plastik dan limbah industri dari sungai-sungai yang bermuara, penangkapan ikan berlebihan, tumpahan minyak, dan kenaikan permukaan laut akibat perubahan iklim. Melindungi teluk berarti melindungi sumber pangan, mata pencaharian, dan keanekaragaman hayati — pengingat bahwa laut dan darat adalah satu sistem yang saling terhubung.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Mengapa Hidrogen Dilrik?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Hidrogen adalah unsur paling melimpah di alam semesta dan punya keunggulan unik sebagai bahan bakar: ketika dibakar atau dipakai di fuel cell, hasil sampingnya hanyalah air — tanpa karbon dioksida. Inilah alasan banyak negara menaruh hidrogen di pusat strategi energi bersih mereka, terutama untuk sektor yang sulit dialiri listrik langsung seperti penerbangan jarak jauh, pelayaran, dan industri berat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Warna-warni Hidrogen$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Hidrogen dikelompokkan berdasarkan cara produksinya: hidrogen abu-abu dibuat dari gas alam dan melepaskan CO2; hidrogen biru juga dari gas alam tetapi CO2-nya ditangkap dan disimpan; hidrogen hijau dibuat dengan elektrolisis air memakai listrik terbarukan — inilah yang benar-benar bersih. Saat ini sebagian besar hidrogen dunia masih abu-abu, dan tantangannya adalah beralih ke hijau dengan biaya terjangkau.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Cara Kerja Fuel Cell$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Fuel cell (sel bahan bakar) mengubah hidrogen menjadi listrik lewat reaksi elektrokimia dengan oksigen, tanpa pembakaran. Hidrogen masuk ke anoda, terpecah menjadi proton dan elektron; elektron mengalir lewat sirkuit menghasilkan arus listrik, lalu bertemu proton dan oksigen di katoda membentuk air. Efisiensinya bisa mencapai 60 persen — jauh di atas mesin bensin biasa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan Nyata Saat Ini$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Hidrogen sudah dipakai di berbagai bidang: bus dan truk fuel cell beroperasi di beberapa kota dunia dengan waktu isi ulang hanya hitungan menit; industri baja dan pupuk memakai hidrogen sebagai bahan baku; sebagian pembangkit listrik mencampur hidrogen ke turbin gas untuk menekan emisi. Di Indonesia, hidrogen hijau mulai dilirik untuk mendukung transisi energi dan potensi ekspor.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tantangan dan Masa Depan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tiga tantangan utama hidrogen adalah: biaya produksi hidrogen hijau yang masih mahal, penyimpanan yang sulit karena hidrogen sangat ringan dan mudah bocor sehingga butuh tekanan tinggi atau suhu sangat rendah, serta infrastruktur distribusi yang belum seluas SPBU atau jaringan listrik. Selain itu, hidrogen sangat mudah terbakar sehingga standar keselamatannya ketat. Para ahli memperkirakan hidrogen akan memainkan peran kunci setelah 2030, seiring turunnya biaya elektroliser dan listrik surya-angin — bukan sebagai pengganti tunggal baterai listrik, melainkan pelengkap: baterai untuk mobil harian, hidrogen untuk truk jarak jauh, kapal, pesawat, dan industri.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, to_jsonb(ARRAY[$txt$Menjelaskan pengertian himpunan dengan bahasa sendiri$txt$, $txt$Menyatakan himpunan dengan tiga cara yang benar$txt$, $txt$Menentukan himpunan kosong, semesta, dan himpunan bagian$txt$, $txt$Melakukan operasi irisan, gabungan, selisih, dan komplemen$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Himpunan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Himpunan adalah kumpulan benda atau objek yang terdefinisi dengan jelas — artinya kita bisa memutuskan dengan pasti apakah sesuatu termasuk anggota atau bukan. Contoh: "himpunan bilangan prima kurang dari 10" adalah himpunan karena anggotanya jelas {2, 3, 5, 7}. Sebaliknya "kumpulan makanan enak" bukan himpunan karena "enak" itu relatif bagi tiap orang. Anggota himpunan ditulis di dalam kurung kurawal dan dipisahkan koma.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Cara Menyatakan Himpunan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Dengan kata-kata (deskripsi): A = {bilangan asli kurang dari 5}.$txt$, $txt$Dengan notasi pembentuk himpunan: A = {x | x < 5, x bilangan asli}.$txt$, $txt$Dengan mendaftar anggotanya: A = {1, 2, 3, 4}. Ketiga cara ini menyatakan himpunan yang sama.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Himpunan Kosong, Semesta, dan Bagian$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Himpunan kosong adalah himpunan yang tidak punya anggota, ditulis {} atau dengan simbol ∅ (bukan {∅}, karena itu himpunan berisi satu anggota yaitu simbol kosong). Contoh: himpunan bilangan prima genap selain 2 adalah himpunan kosong. Himpunan semesta (S) adalah himpunan yang memuat semua objek yang dibicarakan — misalnya S = {1, 2, 3, 4, 5, 6} saat kita membahas dadu. Himpunan A disebut himpunan bagian dari B (ditulis A ⊂ B) jika setiap anggota A juga anggota B, contohnya {2, 4} ⊂ {1, 2, 3, 4, 5}. Setiap himpunan adalah himpunan bagian dari dirinya sendiri, himpunan kosong adalah himpunan bagian dari semua himpunan, dan jumlah himpunan bagian dari himpunan beranggota n adalah 2 pangkat n.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Operasi Himpunan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Irisan (∩): anggota yang ada di kedua himpunan. {1,2,3} ∩ {2,3,4} = {2,3}.$txt$, $txt$Gabungan (∪): semua anggota dari kedua himpunan tanpa pengulangan. {1,2,3} ∪ {2,3,4} = {1,2,3,4}.$txt$, $txt$Selisih (−): anggota A yang bukan anggota B. {1,2,3} − {2,3,4} = {1}.$txt$, $txt$Komplemen (Aᶜ): anggota semesta yang bukan anggota A. Jika S = {1,2,3,4} dan A = {1,2}, maka Aᶜ = {3,4}.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$Soal 1: Diketahui P = {a, b, c, d} dan Q = {c, d, e, f}. Tentukan P ∩ Q dan P ∪ Q. Kunci: P ∩ Q = {c, d}; P ∪ Q = {a, b, c, d, e, f}.$txt$, $txt$Soal 2: Jika S = {1, 2, ..., 10} dan A = {bilangan genap kurang dari 10}, tentukan komplemen A. Kunci: A = {2, 4, 6, 8}, jadi Aᶜ = {1, 3, 5, 7, 9, 10}.$txt$, $txt$Soal 3: Diketahui S = {1, ..., 8}, A = {1, 2, 3, 4}, B = {3, 4, 5, 6}. Tentukan A ∪ B dan A ∩ B. Kunci: A ∪ B = {1, 2, 3, 4, 5, 6}; A ∩ B = {3, 4}.$txt$, $txt$Soal 4: Apakah {∅} sama dengan ∅? Jelaskan alasanmu. Kunci: Tidak sama. ∅ adalah himpunan kosong (0 anggota), sedangkan {∅} beranggotakan satu, yaitu himpunan kosong itu sendiri.$txt$]));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, to_jsonb(ARRAY[$txt$Menjelaskan apa itu suku kata dengan kata-kata sendiri$txt$, $txt$Menyebutkan suku kata dari kata sederhana$txt$, $txt$Memenggal kata menjadi suku kata dengan benar$txt$, $txt$Menyusun suku kata menjadi kata yang bermakna$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Suku Kata?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Suku kata adalah potongan bunyi dari sebuah kata. Coba ucapkan kata "bola" perlahan: bo - la. Nah, kata "bola" punya dua suku kata: "bo" dan "la". Setiap kali mulut kita membuka sekali saat mengucapkan kata, biasanya itulah satu suku kata. Suku kata membantu kita membaca kata yang panjang dengan lebih mudah!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Contoh Suku Kata$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$ma - ta (mata): 2 suku kata$txt$, $txt$ku - da (kuda): 2 suku kata$txt$, $txt$se - pa - tu (sepatu): 3 suku kata$txt$, $txt$bu - ku (buku): 2 suku kata$txt$, $txt$a - yam (ayam): 2 suku kata$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Cara Memenggal Kata$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Memenggal artinya memotong kata menjadi suku-sukunya. Caranya: ucapkan kata perlahan sambil bertepuk tangan setiap ada bunyi yang terpisah. Contoh: "meja" → tepuk dua kali: me - ja. "topi" → to - pi. "jendela" → jen - de - la, tepuk tiga kali! Coba sekarang dengan kata "kursi" dan "pintu".$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Ayo Berlatih!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Penggal kata "sapu" menjadi suku kata!$txt$, $txt$Kata "sekolah" punya berapa suku kata?$txt$, $txt$Susun suku kata "la", "bo" menjadi kata yang benar!$txt$, $txt$Sebutkan 3 kata yang punya 2 suku kata!$txt$, $txt$Permainan tepuk: ucapkan "jendela" perlahan sambil bertepuk — berapa kali kamu bertepuk?$txt$, $txt$Permainan susun: kartu suku kata "ma", "kan", "di" bisa disusun menjadi kata apa saja?$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$sa - pu (2 suku kata).$txt$, $txt$se - ko - lah (3 suku kata).$txt$, $txt$"bola".$txt$, $txt$Contoh: mata, kuda, buku, meja, topi, sapi, roti.$txt$, $txt$jen - de - la: bertepuk 3 kali.$txt$, $txt$"makan", "mandi", atau "dimakan" — semua benar!$txt$]));
