DO $do$ DECLARE v_id uuid; BEGIN
  VALUES (gen_random_uuid(), 'TUT-BAHASA23-001', 'b6666666-6666-6666-6666-666666666666', $$Bahasa Myanmar: Sapaan Dasar$$, 'bahasa-myanmar-sapaan-dasar', $$Pelajari sapaan dasar bahasa Myanmar (Burma): Mingalaba, terima kasih, perkenalan, dan cara melafalkan nada dengan benar.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a')
  ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN SELECT id INTO v_id FROM madevi.articles WHERE business_code = 'TUT-BAHASA23-001'; END IF;
  DELETE FROM madevi.article_blocks WHERE article_id = v_id;
END $do$;

